import XCTest

/// ⌘R on a workroom with no run command opens the Project Settings sheet with the "no command
/// yet" warning (issue #127) — not a silent no-op.
final class RunSettingsPromptUITests: XCTestCase {
  override func setUp() {
    super.setUp()
    continueAfterFailure = false
  }

  private func launchedApp() -> XCUIApplication {
    let app = XCUIApplication()
    // -WorkroomUITestNoRunCommand: the fixture otherwise ALWAYS seeds a fallback run command
    // (AppStore.loadFixture), so without this flag the "no command configured" state this whole
    // test file exists to exercise would never actually hold (found by review, issue #127).
    app.launchArguments += [
      "-WorkroomUITestFixture", "1", "-WorkroomUITestNoRunCommand", "1",
      "-ApplePersistenceIgnoreState", "YES",
    ]
    app.launch()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15))
    // Explicitly select the fixture workroom before sending ⌘R — `runningForeground` proves the
    // window is up, not that a target is selected/ready (outside-voice review flagged this).
    //
    // `.buttons`, NOT `.otherElements`: the sidebar row carries
    // `.accessibilityAddTraits(.isButton)` (`ProjectSidebar.swift`), so XCUITest resolves it as a
    // button and an `otherElements` query matches nothing — which is what silently failed both
    // tests in this file. Same form as `ChangesetDetailUITests`/`HistoryPushStateUITests`, the two
    // other places that select this row.
    let row = app.buttons.matching(
      NSPredicate(
        format: "identifier == %@ AND label == %@", "sidebar.workroom.uitest-room", "uitest-room")
    ).firstMatch
    XCTAssertTrue(row.waitForExistence(timeout: 10), "fixture workroom row should exist")
    row.click()
    return app
  }

  func testCommandRPresentsRunSettingsWithWarningWhenNoCommandConfigured() {
    let app = launchedApp()

    app.typeKey("r", modifierFlags: .command)

    XCTAssertTrue(
      app.staticTexts["projectSettings.runWarning"].waitForExistence(timeout: 10),
      "the warning banner should appear")
    XCTAssertTrue(
      app.textFields["projectSettings.runCommand"].waitForExistence(timeout: 5),
      "the run-command field should be present so the user can define one")
  }

  /// The same branch, reached by CLICK. Since issue #139's follow-up the workroom pane header's Run button
  /// is shown even with no command configured — it exists precisely to lead you here, so a button that
  /// silently did nothing (or wasn't there at all) would be the regression. Written as its own test rather
  /// than folded into the ⌘R one because the keyboard and the click take different doors into
  /// `runOrFocusRunCommand`: the shortcut goes through the selection-scoped overload, the button through
  /// the per-target one.
  func testHeaderRunButtonPresentsRunSettingsWhenNoCommandConfigured() {
    let app = launchedApp()

    let pane = app.descendants(matching: .any).matching(identifier: "workroom.pane").firstMatch
    XCTAssertTrue(pane.waitForExistence(timeout: 10))
    let run = pane.buttons["runCommand.run"]
    XCTAssertTrue(
      run.waitForExistence(timeout: 10),
      "Run should be shown even though this project has no run command configured")
    run.click()

    XCTAssertTrue(
      app.staticTexts["projectSettings.runWarning"].waitForExistence(timeout: 10),
      "clicking Run with nothing configured should open Project Settings, warned")
  }

  /// Regression check for unifying to one sheet presenter (issue #127-eng-1): the pre-existing
  /// "Project Settings…" context-menu entry must keep opening with NO warning banner.
  func testProjectSettingsContextMenuShowsNoWarningBanner() {
    let app = launchedApp()

    // "Project Settings…" lives on the PROJECT row's context menu (ProjectSidebar.swift), not the
    // workroom row's — unlike the ⌘R test above, which acts on the selected workroom.
    app.otherElements["sidebar.project.UITestProject"].rightClick()
    app.menuItems["Project Settings…"].click()

    XCTAssertTrue(
      app.textFields["projectSettings.runCommand"].waitForExistence(timeout: 10),
      "the settings sheet should open")
    XCTAssertFalse(
      app.staticTexts["projectSettings.runWarning"].exists,
      "the plain Project Settings entry must not show the Run warning")
  }
}

import XCTest

/// UI tests for the unpushed badge on History rows and in the changeset detail header.
///
/// The fixture (`FixtureVCSProvider`) seeds all three push states plus both suppression rules, so the
/// pane must show **exactly one** badge: commit 1 is unpushed but is the working copy `@` (suppressed),
/// commit 2 is the only badged row, commit 3 is pushed, commit 4 is unknown, and the two divergent
/// siblings are unpushed but never badge. The exact count is the assertion that matters — a plain
/// `.exists` check would pass a badge-on-every-row bug just as happily.
///
/// The hover card is NOT covered here: XCUITest can't drive `.onHover`. It's covered at the view level
/// by `HistoryCommitCardTests`.
///
/// Run with `make app-uitest` on a real GUI login session.
final class HistoryPushStateUITests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }

  private func launchedApp() -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launch()
    app.activate()
    return app
  }

  private func selectWorkroom(_ app: XCUIApplication) {
    let row = app.buttons.matching(
      NSPredicate(
        format: "identifier == %@ AND label == %@", "sidebar.workroom.uitest-room", "uitest-room")
    ).firstMatch
    if row.waitForExistence(timeout: 10) { row.click() }
  }

  private func el(_ app: XCUIApplication, _ id: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: id).firstMatch
  }

  private func els(_ app: XCUIApplication, _ id: String) -> XCUIElementQuery {
    app.descendants(matching: .any).matching(identifier: id)
  }

  @discardableResult
  private func waitExists(_ e: XCUIElement, _ want: Bool = true, _ timeout: TimeInterval = 8)
    -> Bool
  {
    let p = NSPredicate(format: "exists == %@", NSNumber(value: want))
    return XCTWaiter().wait(
      for: [XCTNSPredicateExpectation(predicate: p, object: e)], timeout: timeout) == .completed
  }

  /// Mirrors `ChangesetDetailUITests.openHistory`: History is a section of the **Changes** pane, so
  /// prime with Files (making the Changes click always a switch), then select the workroom so the
  /// selection re-triggers the load. The section arrives expanded — the fixture pins `inspectorLayout`.
  private func openHistory(_ app: XCUIApplication) {
    XCTAssertTrue(el(app, "activitySection.files").waitForExistence(timeout: 10))
    el(app, "activitySection.files").click()
    XCTAssertTrue(waitExists(el(app, "activitySection.changes")))
    el(app, "activitySection.changes").click()
    XCTAssertTrue(
      el(app, "inspector.header.History").waitForExistence(timeout: 8),
      "the History section renders")

    selectWorkroom(app)

    // Matched by its a11y label, not the glyph: the Changes section header in the same pane carries an
    // identical `arrow.clockwise` refresh button.
    if !els(app, "HistoryRow").element(boundBy: 0).waitForExistence(timeout: 6) {
      let refresh = app.descendants(matching: .any)
        .matching(NSPredicate(format: "label == %@", "Refresh history")).firstMatch
      if refresh.exists { refresh.click() }
    }
    XCTAssertTrue(
      els(app, "HistoryRow").element(boundBy: 0).waitForExistence(timeout: 8),
      "fixture history rows render")
  }

  /// The row for a specific fixture commit, matched by its short id rather than by position.
  ///
  /// Position stopped being a reliable way to name a commit when the History list became a
  /// `LazyVStack` (WORKROOM-2B): unrealized rows are absent from the accessibility tree, so
  /// `element(boundBy: 2)` can silently mean a different commit than the test intends — and still pass.
  /// The short id leads each row's accessibility label for exactly this reason. Scoped to `staticTexts`
  /// (the combined row leaf) to keep the predicate query off the whole snapshot.
  private func historyRow(_ app: XCUIApplication, shortID: String) -> XCUIElement {
    // `descendants(matching: .any)`, not `staticTexts`: SwiftUI's combined row leaf is not reliably a
    // static text, and an identifier-scoped query stays indexed (fast) even though a label predicate
    // rides along.
    els(app, "HistoryRow")
      .matching(NSPredicate(format: "label BEGINSWITH %@", shortID))
      .firstMatch
  }

  /// Exactly one row badges, and it isn't every row: this is the suppression proof. `@` (unpushed),
  /// pushed and unknown rows must all stay clean.
  func testExactlyOneRowShowsTheUnpushedBadge() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)

    XCTAssertTrue(
      els(app, "HistoryRowUnpushed").element(boundBy: 0).waitForExistence(timeout: 8),
      "the unpushed row badges")
    let badges = els(app, "HistoryRowUnpushed").count
    let rows = els(app, "HistoryRow").count
    XCTAssertEqual(badges, 1, "only the one genuinely-unpushed non-@ commit badges")
    XCTAssertLessThan(badges, rows, "the badge is per-commit, not decoration on the whole list")
  }

  /// Expanding the divergence disclosure must not add badges: the sibling copies are unpushed in the
  /// fixture, but they sit off the `::@` line and their rows deliberately don't carry the marker.
  func testDivergentSiblingsDoNotBadge() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)
    XCTAssertTrue(
      els(app, "HistoryRowUnpushed").element(boundBy: 0).waitForExistence(timeout: 8))
    XCTAssertEqual(els(app, "HistoryRowUnpushed").count, 1)

    let toggle = el(app, "HistoryRowDiverges")
    XCTAssertTrue(toggle.waitForExistence(timeout: 8))
    toggle.click()
    XCTAssertTrue(
      els(app, "HistoryDivergentSibling").element(boundBy: 1).waitForExistence(timeout: 6),
      "the sibling copies appear")

    XCTAssertEqual(
      els(app, "HistoryRowUnpushed").count, 1,
      "expanding the divergence expander adds rows but no badges")
  }

  /// Matched app-wide on `value`, not by identifier and not scoped to the detail element.
  ///
  /// Two facts about how SwiftUI exposes this header, both verified by dumping the tree: the element
  /// carrying `identifier: 'ChangesetDetail'` is a LEAF `StaticText` whose value is just the commit
  /// summary — the metadata line is a sibling, not a descendant — and that metadata line is one combined
  /// `StaticText` whose VALUE concatenates its children ("…, Not pushed, …"). So a scoped or
  /// identifier-based query finds nothing (the same reason `ChangesetDetailUITests` matches the `+N −M`
  /// summary on `value CONTAINS`).
  ///
  /// Matching on `value` and not `label` is what keeps this honest: the History row's badge carries
  /// "Not pushed" as its accessibility LABEL, so a label match would find the row and pass regardless of
  /// what the header shows.
  ///
  /// Scoped to `staticTexts`, not `descendants(matching: .any)`: a predicate query over EVERY element
  /// has to evaluate the whole snapshot, and since History joined the Changes stack the inspector holds
  /// three sections' worth of rows at once — the unscoped version started failing with "Timed out while
  /// evaluating UI query" (identifier queries are indexed and stayed fast, which is why only the
  /// predicate ones broke).
  private func headerSaysNotPushed(_ app: XCUIApplication) -> XCUIElement {
    app.staticTexts.matching(NSPredicate(format: "value CONTAINS %@", "Not pushed")).firstMatch
  }

  /// Opening the badged commit states the same fact in the detail header — a badge that vanishes when
  /// you click the row would read as a bug.
  func testChangesetHeaderShowsTheUnpushedMarker() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)

    // Fixture commit 2 is the badged one — named by its short id, not by row position.
    let badged = historyRow(app, shortID: "fixc0002")
    XCTAssertTrue(
      badged.waitForExistence(timeout: 8), "the badged fixture commit's row is on screen")
    badged.click()
    XCTAssertTrue(waitExists(el(app, "ChangesetDetail")), "the changeset detail opens")
    XCTAssertTrue(
      waitExists(headerSaysNotPushed(app)), "the detail header states the commit isn't pushed")
  }

  /// And the pushed commit's detail says nothing: the marker is a claim about this commit, not a
  /// permanent header fixture.
  func testChangesetHeaderOmitsTheMarkerForAPushedCommit() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)

    // Fixture commit 3 is `.pushed`.
    let pushed = historyRow(app, shortID: "fixc0003")
    XCTAssertTrue(
      pushed.waitForExistence(timeout: 8), "the pushed fixture commit's row is on screen")
    pushed.click()
    XCTAssertTrue(waitExists(el(app, "ChangesetDetail")), "the changeset detail opens")
    XCTAssertFalse(
      headerSaysNotPushed(app).exists, "a pushed commit's header carries no unpushed marker")
  }
}

import XCTest

/// History at scale — the UI-tier half of the WORKROOM-2B App Hang fix.
///
/// Launched with `-WorkroomUITestManyCommits 800`, so the fixture serves 800 commits across seven
/// authors. Two properties matter here, and neither is visible to a unit test:
///
/// 1. **The pane realizes only what it draws.** The eager `VStack` this replaced built every loaded row
///    — 800 rows of MD5 + Gravatar-URL + avatar work per body pass. If the count of realized rows is in
///    the hundreds, the list went back to being eager.
/// 2. **The app stays interactive at that size.** A 2-second budget, not the 8 seconds an earlier draft
///    used: 8 seconds would pass straight through the very hang being fixed.
///
/// Plus the lazy-stack failure modes that only exist once a list is lazy: scrolling away and back
/// (recycled row state), expanding a row mid-list, and selecting a row that started off-screen.
///
/// Run per-method: `xcodebuild … -only-testing:WorkroomAppUITests/HistoryStressUITests/<method>`.
final class HistoryStressUITests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }

  private func launchedApp(commits: Int = 800) -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-WorkroomUITestManyCommits", String(commits)]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launch()
    app.activate()
    return app
  }

  private func el(_ app: XCUIApplication, _ id: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: id).firstMatch
  }

  private func els(_ app: XCUIApplication, _ id: String) -> XCUIElementQuery {
    app.descendants(matching: .any).matching(identifier: id)
  }

  private func selectWorkroom(_ app: XCUIApplication) {
    let row = app.buttons.matching(
      NSPredicate(
        format: "identifier == %@ AND label == %@", "sidebar.workroom.uitest-room", "uitest-room")
    ).firstMatch
    if row.waitForExistence(timeout: 10) { row.click() }
  }

  /// Same recipe as `HistoryPushStateUITests.openHistory`: prime with Files so the Changes click is
  /// always a switch, then select the workroom so the selection re-triggers the load.
  private func openHistory(_ app: XCUIApplication) {
    XCTAssertTrue(el(app, "activitySection.files").waitForExistence(timeout: 10))
    el(app, "activitySection.files").click()
    XCTAssertTrue(el(app, "activitySection.changes").waitForExistence(timeout: 8))
    el(app, "activitySection.changes").click()
    XCTAssertTrue(el(app, "inspector.header.History").waitForExistence(timeout: 8))

    selectWorkroom(app)

    if !els(app, "HistoryRow").element(boundBy: 0).waitForExistence(timeout: 8) {
      let refresh = app.descendants(matching: .any)
        .matching(NSPredicate(format: "label == %@", "Refresh history")).firstMatch
      if refresh.exists { refresh.click() }
    }
    XCTAssertTrue(
      els(app, "HistoryRow").element(boundBy: 0).waitForExistence(timeout: 10),
      "the stress fixture's history rows render")
  }

  func testLargeHistoryRealizesOnlyTheVisibleRows() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)

    // Anti-vacuity guard: with only the default five-commit fixture, "fewer than 100 realized rows"
    // would pass while proving nothing. Stress commits carry `s…` short ids (the default fixture's are
    // `fixc000…`), and each row's accessibility label leads with its short id — so this asserts the
    // stress page is genuinely in play.
    //
    // Note what is NOT used here: "Load more". That button sits BELOW 800 rows, so a lazy list
    // legitimately hasn't realized it — its absence is evidence FOR laziness, not against the fixture.
    XCTAssertTrue(
      els(app, "HistoryRow").matching(NSPredicate(format: "label BEGINSWITH %@", "s000")).firstMatch
        .waitForExistence(timeout: 8),
      "the stress fixture's synthetic commits must be what the pane is showing")

    let realized = els(app, "HistoryRow").count
    XCTAssertGreaterThan(realized, 0, "some rows must be on screen")
    // No exact number: how far past the viewport SwiftUI realizes is its business and moves between OS
    // releases. "Nowhere near all 800" is the property that distinguishes lazy from eager.
    XCTAssertLessThan(
      realized, 100,
      "\(realized) of 800 rows are in the accessibility tree — that many realized rows means the list "
        + "is building the whole window again (the WORKROOM-2B amplifier)")
  }

  func testLargeHistoryStaysInteractive() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)

    let started = Date()
    els(app, "HistoryRow").element(boundBy: 0).click()
    XCTAssertTrue(
      el(app, "ChangesetDetail").waitForExistence(timeout: 2),
      "clicking a row on an 800-commit page must open its changeset within 2s — a budget under the "
        + "2000 ms app-hang threshold, so a stalled main thread fails instead of passing slowly")
    XCTAssertLessThan(Date().timeIntervalSince(started), 2.0)
  }

  func testScrollingAwayAndBackKeepsRowsUsable() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)
    let firstRow = els(app, "HistoryRow").element(boundBy: 0)
    let scroller = app.scrollViews.firstMatch
    XCTAssertTrue(scroller.waitForExistence(timeout: 8))

    // Recycled row state is the lazy-stack hazard: rows destroyed on scroll-out must come back live,
    // not blank or stale.
    scroller.scroll(byDeltaX: 0, deltaY: -1200)
    XCTAssertTrue(els(app, "HistoryRow").element(boundBy: 0).waitForExistence(timeout: 8))
    scroller.scroll(byDeltaX: 0, deltaY: 1200)

    XCTAssertTrue(
      firstRow.waitForExistence(timeout: 8), "the top rows come back after scrolling back")
    firstRow.click()
    XCTAssertTrue(
      el(app, "ChangesetDetail").waitForExistence(timeout: 4),
      "a recycled row still opens its changeset")
  }

  func testRowFurtherDownThePageOpensItsOwnChangeset() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)
    let scroller = app.scrollViews.firstMatch
    XCTAssertTrue(scroller.waitForExistence(timeout: 8))

    // A row that started off-screen: scrolling realizes it, and clicking it must select THAT commit —
    // the case index-based selection can't express once rows come and go.
    scroller.scroll(byDeltaX: 0, deltaY: -600)
    let row = els(app, "HistoryRow").element(boundBy: 1)
    XCTAssertTrue(row.waitForExistence(timeout: 8))
    let label = row.label
    row.click()

    XCTAssertTrue(el(app, "ChangesetDetail").waitForExistence(timeout: 4))
    // The row's label leads with the commit's short id; the detail must be showing that commit.
    let shortID = String(label.prefix(while: { $0 != "," }))
    XCTAssertTrue(
      app.staticTexts.matching(
        NSPredicate(format: "value CONTAINS %@ OR label CONTAINS %@", shortID, shortID)
      )
      .firstMatch.waitForExistence(timeout: 4),
      "the changeset that opened belongs to the row that was clicked (\(shortID))")
  }
}

